figures.asymptoteSource:
// Tree diagram for the Fundamental Counting Principle: 2 appetizers, 3 mains, 2 desserts.
// Two-argument size fixes the output box, so the declared 16/3 is exact.
size(480,360);
pen thin = gray(0.6) + 1;
pen thick = black + 1.5;
real x0 = 0, dx = 140;
real y0 = 160, dy = 50;
// Appetizers
label("Appetizer", (x0, y0+20), N);
dot((x0-dx, y0+dy), black+3pt);
dot((x0-dx, y0-dy), black+3pt);
draw((x0-dx, y0+dy)--(x0+dx, y0+2*dy), thin);
draw((x0-dx, y0+dy)--(x0+dx, y0), thin);
draw((x0-dx, y0+dy)--(x0+dx, y0-2*dy), thin);
draw((x0-dx, y0-dy)--(x0+dx, y0+2*dy), thin);
draw((x0-dx, y0-dy)--(x0+dx, y0), thin);
draw((x0-dx, y0-dy)--(x0+dx, y0-2*dy), thin);
label("$A_1$", (x0-dx, y0+dy), W);
label("$A_2$", (x0-dx, y0-dy), W);
label("$M_1$", (x0, y0+2*dy), N);
label("$M_2$", (x0, y0), N);
label("$M_3$", (x0, y0-2*dy), N);
// Desserts
label("Dessert", (x0+2*dx, y0+20), N);
draw((x0+dx, y0+2*dy)--(x0+2*dx, y0+3*dy), thick);
draw((x0+dx, y0+2*dy)--(x0+2*dx, y0+dy), thick);
draw((x0+dx, y0)--(x0+2*dx, y0+dy), thick);
draw((x0+dx, y0)--(x0+2*dx, y0-dy), thick);
draw((x0+dx, y0-2*dy)--(x0+2*dx, y0+dy), thick);
draw((x0+dx, y0-2*dy)--(x0+2*dx, y0-dy), thick);
draw((x0+dx, y0-2*dy)--(x0+2*dx, y0-3*dy), thick);
label("$D_1$", (x0+2*dx, y0+3*dy), E);
label("$D_2$", (x0+2*dx, y0+dy), E);
label("$D_1$", (x0+2*dx, y0-dy), E);
label("$D_2$", (x0+2*dx, y0-3*dy), E);
label("$2 \times 3 \times 2 = 12$ meals", (x0+dx, y0-4.5*dy), S);
